package com.hbm.client.generator.industrialmemorial;
import com.hbm.client.model.*;import com.hbm.machine.generator.industrialmemorial.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Source RenderIGenerator static Body/Rotor, smooth HFR authored normals, no culling. */
public final class IndustrialMemorialRenderer implements BlockEntityRenderer<IndustrialMemorialBlockEntity> {
 private static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/machines/igen.obj"),TEXTURE=ResourceLocation.parse("hbm:textures/models/machines/igen.png");public IndustrialMemorialRenderer(BlockEntityRendererProvider.Context context){}static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);}static void parts(PoseStack pose,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.renderOnly(mesh(),pose,buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR,"Body","Rotor");}
 @Override public void render(IndustrialMemorialBlockEntity machine,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){float yaw=switch(DummyableBlock.facing(machine.getBlockState())){case NORTH->180;case WEST->270;case EAST->90;default->0;};var matrix=new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(yaw)).scale(1F/6).translate(0,0,-.5F);LegacyContactShadows.render(machine,mesh(),matrix,pose,buffers);pose.pushPose();pose.translate(.5,0,.5);pose.mulPose(Axis.YP.rotationDegrees(yaw));pose.scale(1F/6,1F/6,1F/6);pose.translate(0,0,-.5);parts(pose,buffers,light,overlay);pose.popPose();}
 @Override public boolean shouldRenderOffScreen(IndustrialMemorialBlockEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(IndustrialMemorialBlockEntity machine){return new AABB(machine.getBlockPos());}
}
